GKYL_CU_DH static double
kernel_dg_gyrokinetic_vol_1x1v_ser_p1(
  const struct gkyl_dg_eqn *eqn, const double *xc, const double *dx, const int *idx,
  const double *qIn, double *GKYL_RESTRICT qRhsOut
)
{
  struct dg_gyrokinetic *gyrokinetic = container_of(eqn, struct dg_gyrokinetic, eqn);

  int vel_idx[2];
  for (int d = gyrokinetic->cdim; d < gyrokinetic->pdim; d++) {
    vel_idx[d - gyrokinetic->cdim] = idx[d];
  }

  long cidx = gkyl_range_idx(&gyrokinetic->conf_range, idx);
  long vidx = gkyl_range_idx(&gyrokinetic->vel_map->local_vel, vel_idx);
  long pidx = gkyl_range_idx(&gyrokinetic->phase_range, idx);
