gyrokinetic/apps/gkyl_gyrokinetic_priv.h:2205:  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
gyrokinetic/apps/gkyl_gyrokinetic_priv.h:2219:  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls,
