        const struct gkyl_dg_surf_geom *dgs = gkyl_dg_geom_get_surf(up->dg_geom, dir, idx_edge);
        const struct gkyl_gk_dg_surf_geom *gkdgs =
          gkyl_gk_dg_geom_get_surf(up->gk_dg_geom, dir, idx_edge);

        const double *jacgeo_rat_surfL_d =
          gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf);
        const double *jacgeo_rat_surfR_d =
          gkyl_array_cfetch(up->gk_geom->geo_surf[dir].jacobgeo_ratio, loc_conf_ext);

        double *flux_surf_ext_d = gkyl_array_fetch(flux_surf, loc_phase_ext);
        double *alpha_surf_ext_d = gkyl_array_fetch(alpha_surf, loc_phase_ext);

