#include <gkyl_gyrokinetic_priv.h>

#include <math.h>

static void
gk_species_collisionless_influx_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless_influx *influx,
  struct gkyl_array *flux_surf, const struct gkyl_array *alpha_surf
)
{
  // No collisionless surface-flux modification is configured.
}

static void
gk_species_collisionless_influx_sheath_edge(
  const struct gk_species *species, const struct gkyl_range *skin_range, int par_dir,
  bool is_lower, struct gkyl_array *flux_surf, const struct gkyl_array *alpha_surf
)
{
  int pdim = species->local.ndim;
  int cdim = par_dir + 1;
  int face_basis = alpha_surf->ncomp / cdim;
  int conf_face_nodes = face_basis / 6;
  int vpar_dir = cdim;
  int vpar_sum = species->local.lower[vpar_dir] + species->local.upper[vpar_dir];
  double edge_sign = is_lower ? -1.0 : 1.0;

  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, skin_range);
  while (gkyl_range_iter_next(&iter)) {
    int flux_idx[GKYL_MAX_DIM], reflected_idx[GKYL_MAX_DIM];
    gkyl_copy_int_arr(pdim, iter.idx, flux_idx);
    if (!is_lower) {
      flux_idx[par_dir] += 1;
    }
    gkyl_copy_int_arr(pdim, flux_idx, reflected_idx);
    reflected_idx[vpar_dir] = vpar_sum - iter.idx[vpar_dir];

    long flux_loc = gkyl_range_idx(&species->local_ext, flux_idx);
    long reflected_loc = gkyl_range_idx(&species->local_ext, reflected_idx);
    double *flux = gkyl_array_fetch(flux_surf, flux_loc) + par_dir * face_basis;
    const double *alpha = gkyl_array_cfetch(alpha_surf, flux_loc) + par_dir * face_basis;
    double *reflected_flux = gkyl_array_fetch(flux_surf, reflected_loc) + par_dir * face_basis;
    const double *reflected_alpha =
      gkyl_array_cfetch(alpha_surf, reflected_loc) + par_dir * face_basis;

    for (int conf_node = 0; conf_node < conf_face_nodes; ++conf_node) {
      for (int mu_node = 0; mu_node < 2; ++mu_node) {
        for (int vpar_node = 0; vpar_node < 3; ++vpar_node) {
          int node = 6 * conf_node + 3 * mu_node + vpar_node;
          int reflected_node = 6 * conf_node + 3 * mu_node + 2 - vpar_node;

          // The legacy sheath ghost fill has already applied the electrostatic
          // cutoff. A zero incoming flux therefore denotes an absorbed state.
          // Only replace a genuinely incoming, reflected flux.
          if (edge_sign * alpha[node] > 0.0 && edge_sign * reflected_alpha[reflected_node] < 0.0 &&
              reflected_flux[reflected_node] != 0.0) {
            reflected_flux[reflected_node] = -flux[node];
          }
        }
      }
    }
  }
}

static void
gk_species_collisionless_influx_sheath(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless_influx *influx,
  struct gkyl_array *flux_surf, const struct gkyl_array *alpha_surf
)
{
  int par_dir = app->cdim - 1;
  if (influx->lower_sheath) {
    gk_species_collisionless_influx_sheath_edge(
      species, &species->local_lower_skin[par_dir], par_dir, true, flux_surf, alpha_surf
    );
  }
  if (influx->upper_sheath) {
    gk_species_collisionless_influx_sheath_edge(
      species, &species->local_upper_skin[par_dir], par_dir, false, flux_surf, alpha_surf
    );
  }
}

void
gk_species_collisionless_influx_init(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless_influx *influx
)
{
  *influx = (struct gk_collisionless_influx) {
    .advance = gk_species_collisionless_influx_disabled,
  };

  // The p1 sheath reflection kernels are defined for two velocity dimensions.
  // Keep unsupported discretizations on the legacy sheath path until they get
  // a matching nodal surface-flux operation.
  int vdim = gks->local.ndim - app->cdim;
  int par_dir = app->cdim - 1;
  if (app->use_gpu || gks->info.charge >= 0.0 || gks->basis.poly_order != 1 || vdim != 2 ||
      gks->collisionless.collisionless_id == GKYL_GK_COLLISIONLESS_NONE ||
      gks->collisionless.collisionless_id == GKYL_GK_COLLISIONLESS_PASSIVE) {
    return;
  }

  influx->lower_sheath = gks->lower_bc[par_dir].type == GKYL_BC_GK_SPECIES_SHEATH;
  influx->upper_sheath = gks->upper_bc[par_dir].type == GKYL_BC_GK_SPECIES_SHEATH;
  if (influx->lower_sheath || influx->upper_sheath) {
    influx->advance = gk_species_collisionless_influx_sheath;
  }
}

void
gk_species_collisionless_influx_advance(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless_influx *influx,
  struct gkyl_array *flux_surf, const struct gkyl_array *alpha_surf
)
{
  influx->advance(app, species, influx, flux_surf, alpha_surf);
}

void
gk_species_collisionless_influx_release(struct gk_collisionless_influx *influx)
{
  // No allocations in the initial local-sheath operation.
}

