__global__ static void
gk_species_collisionless_influx_sheath_cu_kernel(
  struct gkyl_range phase_ext_range, struct gkyl_range skin_range, int cdim, bool is_lower,
  struct gkyl_array *flux_surf, const struct gkyl_array *alpha_surf
)
{
  int pdim = skin_range.ndim;
  int par_dir = cdim - 1;
  int face_basis = alpha_surf->ncomp / cdim;
  int conf_face_nodes = face_basis / 6;
  int vpar_dir = cdim;
  int vpar_sum = phase_ext_range.lower[vpar_dir] + phase_ext_range.upper[vpar_dir];
  double edge_sign = is_lower ? -1.0 : 1.0;

  for (unsigned long lin = threadIdx.x + blockIdx.x * blockDim.x; lin < skin_range.volume;
       lin += gridDim.x * blockDim.x) {
    int skin_idx[GKYL_MAX_DIM], flux_idx[GKYL_MAX_DIM], reflected_idx[GKYL_MAX_DIM];
    gkyl_sub_range_inv_idx(&skin_range, lin, skin_idx);
    gkyl_copy_int_arr(pdim, skin_idx, flux_idx);
    if (!is_lower) {
      flux_idx[par_dir] += 1;
    }
    gkyl_copy_int_arr(pdim, flux_idx, reflected_idx);
    reflected_idx[vpar_dir] = vpar_sum - skin_idx[vpar_dir];

    long flux_loc = gkyl_range_idx(&phase_ext_range, flux_idx);
    long reflected_loc = gkyl_range_idx(&phase_ext_range, reflected_idx);
    double *flux = (double *)gkyl_array_fetch(flux_surf, flux_loc) + par_dir * face_basis;
    const double *alpha =
      (const double *)gkyl_array_cfetch(alpha_surf, flux_loc) + par_dir * face_basis;
    double *reflected_flux =
      (double *)gkyl_array_fetch(flux_surf, reflected_loc) + par_dir * face_basis;
    const double *reflected_alpha =
      (const double *)gkyl_array_cfetch(alpha_surf, reflected_loc) + par_dir * face_basis;

    for (int conf_node = 0; conf_node < conf_face_nodes; ++conf_node) {
      for (int mu_node = 0; mu_node < 2; ++mu_node) {
        for (int vpar_node = 0; vpar_node < 3; ++vpar_node) {
          int node = 6 * conf_node + 3 * mu_node + vpar_node;
          int reflected_node = 6 * conf_node + 3 * mu_node + 2 - vpar_node;
          if (edge_sign * alpha[node] > 0.0 && edge_sign * reflected_alpha[reflected_node] < 0.0 &&
              reflected_flux[reflected_node] != 0.0) {
            reflected_flux[reflected_node] = -flux[node];
          }
        }
      }
    }
  }
}

