// Object type
typedef struct gkyl_boundary_flux gkyl_boundary_flux;

/**
 * Create new updater to compute fluxes through the boundary surface due to the
 * surface terms in one or more equation systems (terms).
 *
 * @param dir Direction in which to apply BC.
 * @param edge Lower or upper edge at which to apply BC (see gkyl_edge_loc).
 * @param grid_cu Grid object (on device)
 * @param skin_r Skin range.
 * @param ghost_r Ghost range.
 * @param num_eqns Number of equation objects.
 * @param eqns Equation objects.
 * @param use_gpu Boolean to indicate whether to use the GPU.
 * @return New updater pointer.
 */
struct gkyl_boundary_flux *gkyl_boundary_flux_new(
  int dir, enum gkyl_edge_loc edge, const struct gkyl_rect_grid *grid,
  const struct gkyl_range *skin_r, const struct gkyl_range *ghost_r, int num_equations,
  const struct gkyl_dg_eqn **eqns, bool use_gpu
);

/**
 * Compute the boundary flux.
 *
 * @param up Boundary flux updater.
 * @param fIn Input distribution function.
 * @param rhs Output flux.
 */
void gkyl_boundary_flux_advance(
  gkyl_boundary_flux *up, const struct gkyl_array *fIn, struct gkyl_array *fluxOut
);

/**
 * Free memory associated with this updater.
 *
 * @param up Updater to delete.
 */
void gkyl_boundary_flux_release(gkyl_boundary_flux *up);
#pragma once

#include <gkyl_boundary_flux.h>

struct gkyl_boundary_flux {
  int dir; // Direction perpendicular to the sheath boundary.
  enum gkyl_edge_loc edge; // Lower or upper boundary.
  struct gkyl_rect_grid grid; // Phase-space grid object.
  struct gkyl_range skin_r, ghost_r; // Skin and ghost ranges.
  int num_eqns; // Number of equation objects.
  struct gkyl_dg_eqn **eqns; // Equation objects.
  struct gkyl_dg_eqn **eqns_ho; // Equation objects on the host.
  bool use_gpu; // Whether to run on GPU.

  uint32_t flags;
  struct gkyl_boundary_flux *on_dev; // pointer to itself or device data
};

#ifdef GKYL_HAVE_CUDA
/**
 * Create new boundary_flux updater on the GPU.
 *
 * @param dir Direction in which to apply BC.
 * @param edge Lower or upper edge at which to apply BC (see gkyl_edge_loc).
 * @param grid Grid object (on device)
 * @param skin_r Skin range.
 * @param ghost_r Ghost range.
 * @param num_eqns Number of equation objects.
 * @param eqns Equation objects.
 * @return New updater pointer.
 */
gkyl_boundary_flux *gkyl_boundary_flux_cu_dev_new(
  int dir, enum gkyl_edge_loc edge, const struct gkyl_rect_grid *grid,
  const struct gkyl_range *skin_r, const struct gkyl_range *ghost_r, int num_eqns,
  const struct gkyl_dg_eqn **eqns
);

/**
 * Compute the boundary flux on the GPU.
 *
 * @param up Boundary flux updater.
 * @param fIn Input distribution function.
 * @param fluxOut Output flux.
 */
void gkyl_boundary_flux_advance_cu(
  gkyl_boundary_flux *up, const struct gkyl_array *fIn, struct gkyl_array *fluxOut
);
#endif
#include <assert.h>
#include <math.h>
#include <time.h>
#include <float.h>

#include <gkyl_alloc.h>
#include <gkyl_alloc_flags_priv.h>
#include <gkyl_array_ops.h>
#include <gkyl_boundary_flux.h>
#include <gkyl_boundary_flux_priv.h>
#include <gkyl_util.h>

gkyl_boundary_flux *
gkyl_boundary_flux_new(
  int dir, enum gkyl_edge_loc edge, const struct gkyl_rect_grid *grid,
  const struct gkyl_range *skin_r, const struct gkyl_range *ghost_r, int num_eqns,
  const struct gkyl_dg_eqn **eqns, bool use_gpu
)
{
#ifdef GKYL_HAVE_CUDA
  if (use_gpu) {
    return gkyl_boundary_flux_cu_dev_new(dir, edge, grid, skin_r, ghost_r, num_eqns, eqns);
  }
#endif

  gkyl_boundary_flux *up = gkyl_malloc(sizeof(gkyl_boundary_flux));

  up->dir = dir;
  up->edge = edge;
  up->grid = *grid;
  up->skin_r = *skin_r;
  up->ghost_r = *ghost_r;
  up->use_gpu = use_gpu;

  up->num_eqns = num_eqns;
  up->eqns = gkyl_malloc(up->num_eqns * sizeof(struct gkyl_dg_eqn *));
  for (int i = 0; i < up->num_eqns; i++) {
    up->eqns[i] = gkyl_dg_eqn_acquire(eqns[i]);
  }

  up->eqns_ho = up->eqns;

  up->flags = 0;
  GKYL_CLEAR_CU_ALLOC(up->flags);

  up->on_dev = up;

  return up;
}

void
gkyl_boundary_flux_advance(
  gkyl_boundary_flux *up, const struct gkyl_array *fIn, struct gkyl_array *fluxOut
)
{
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    gkyl_boundary_flux_advance_cu(up, fIn, fluxOut);
    return;
  }
#endif

  int idx_s[GKYL_MAX_DIM];
  double xc_g[GKYL_MAX_DIM], xc_s[GKYL_MAX_DIM];

  struct gkyl_range_iter iter;
  gkyl_range_iter_init(&iter, &up->ghost_r);
  while (gkyl_range_iter_next(&iter)) {
    int *idx_g = iter.idx;
    gkyl_copy_int_arr(up->ghost_r.ndim, idx_g, idx_s);
    idx_s[up->dir] = up->edge == GKYL_LOWER_EDGE ? idx_g[up->dir] + 1 : idx_g[up->dir] - 1;

    gkyl_rect_grid_cell_center(&up->grid, idx_g, xc_g);
    gkyl_rect_grid_cell_center(&up->grid, idx_s, xc_s);

    long linidx_g = gkyl_range_idx(&up->ghost_r, idx_g);
    long linidx_s = gkyl_range_idx(&up->skin_r, idx_s);

    const double *fIn_s = gkyl_array_cfetch(fIn, linidx_s);
    const double *fIn_g = gkyl_array_cfetch(fIn, linidx_g);
    double *fluxOut_g = gkyl_array_fetch(fluxOut, linidx_g);

    for (int i = 0; i < up->num_eqns; i++) {
      up->eqns[i]->boundary_diag_term(
        up->eqns[i], up->dir, xc_s, xc_g, up->grid.dx, up->grid.dx, idx_s, idx_g,
        up->edge == GKYL_LOWER_EDGE ? -1 : 1, fIn_s, fIn_g, fluxOut_g
      );
    }
  }
}

void
gkyl_boundary_flux_release(gkyl_boundary_flux *up)
{
#ifdef GKYL_HAVE_CUDA
  if (up->use_gpu) {
    gkyl_cu_free(up->eqns);
  }
#endif
  for (int i = 0; i < up->num_eqns; i++) {
    gkyl_dg_eqn_release(up->eqns_ho[i]);
  }
  gkyl_free(up->eqns_ho);

  if (GKYL_IS_CU_ALLOC(up->flags)) {
    gkyl_cu_free(up->on_dev);
  }
  gkyl_free(up);
}
/* -*- c++ -*- */
#include <float.h>

extern "C" {
#include <gkyl_alloc.h>
#include <gkyl_alloc_flags_priv.h>
#include <gkyl_boundary_flux.h>
#include <gkyl_boundary_flux_priv.h>
}

struct gkyl_boundary_flux *
gkyl_boundary_flux_cu_dev_new(
  int dir, enum gkyl_edge_loc edge, const struct gkyl_rect_grid *grid,
  const struct gkyl_range *skin_r, const struct gkyl_range *ghost_r, int num_eqns,
  const struct gkyl_dg_eqn **eqns
)
{
  struct gkyl_boundary_flux *up =
    (struct gkyl_boundary_flux *)gkyl_malloc(sizeof(struct gkyl_boundary_flux));

  up->dir = dir;
  up->edge = edge;
  up->grid = *grid;
  up->skin_r = *skin_r;
  up->ghost_r = *ghost_r;
  up->use_gpu = true;

  // Acquire pointers to on_dev objects so memcpy below copies those too.
  up->flags = 0;
  GKYL_SET_CU_ALLOC(up->flags);

  up->num_eqns = num_eqns;

  up->eqns_ho = (struct gkyl_dg_eqn **)gkyl_malloc(up->num_eqns * sizeof(struct gkyl_dg_eqn *));
  struct gkyl_dg_eqn **eqns_ho_dev =
    (struct gkyl_dg_eqn **)gkyl_malloc(up->num_eqns * sizeof(struct gkyl_dg_eqn *));
  for (int i = 0; i < up->num_eqns; i++) {
    up->eqns_ho[i] = gkyl_dg_eqn_acquire(eqns[i]);
    eqns_ho_dev[i] = up->eqns_ho[i]->on_dev;
  }

  up->eqns = (struct gkyl_dg_eqn **)gkyl_cu_malloc(up->num_eqns * sizeof(struct gkyl_dg_eqn *));
  gkyl_cu_memcpy(
    up->eqns, eqns_ho_dev, up->num_eqns * sizeof(struct gkyl_dg_eqn *), GKYL_CU_MEMCPY_H2D
  );

  struct gkyl_boundary_flux *up_cu =
    (struct gkyl_boundary_flux *)gkyl_cu_malloc(sizeof(struct gkyl_boundary_flux));
  gkyl_cu_memcpy(up_cu, up, sizeof(struct gkyl_boundary_flux), GKYL_CU_MEMCPY_H2D);
  up->on_dev = up_cu;

  gkyl_free(eqns_ho_dev);

  return up;
}

__global__ static void
gkyl_boundary_flux_advance_cu_ker(
  const struct gkyl_boundary_flux *up, const struct gkyl_array *fIn, struct gkyl_array *fluxOut
)
{
  int idx_g[GKYL_MAX_DIM], idx_s[GKYL_MAX_DIM];
  double xc_g[GKYL_MAX_DIM], xc_s[GKYL_MAX_DIM];

  for (unsigned long tid = threadIdx.x + blockIdx.x * blockDim.x; tid < up->ghost_r.volume;
       tid += blockDim.x * gridDim.x) {
    gkyl_sub_range_inv_idx(&up->ghost_r, tid, idx_g);

    gkyl_copy_int_arr(up->ghost_r.ndim, idx_g, idx_s);
    idx_s[up->dir] = up->edge == GKYL_LOWER_EDGE ? idx_g[up->dir] + 1 : idx_g[up->dir] - 1;

    gkyl_rect_grid_cell_center(&up->grid, idx_g, xc_g);
    gkyl_rect_grid_cell_center(&up->grid, idx_s, xc_s);

    long linidx_g = gkyl_range_idx(&up->ghost_r, idx_g);
    long linidx_s = gkyl_range_idx(&up->skin_r, idx_s);

    const double *fg_c = (const double *)gkyl_array_cfetch(fIn, linidx_g);
    const double *fs_c = (const double *)gkyl_array_cfetch(fIn, linidx_s);
    double *fluxOut_g = (double *)gkyl_array_fetch(fluxOut, linidx_g);

    for (int i = 0; i < up->num_eqns; i++) {
      up->eqns[i]->boundary_diag_term(
        up->eqns[i], up->dir, xc_s, xc_g, up->grid.dx, up->grid.dx, idx_s, idx_g,
        up->edge == GKYL_LOWER_EDGE ? -1 : 1, fs_c, fg_c, fluxOut_g
      );
    }
  }
}

void
gkyl_boundary_flux_advance_cu(
  struct gkyl_boundary_flux *up, const struct gkyl_array *fIn, struct gkyl_array *fluxOut
)
{
