}

static void
gk_species_release_dynamic(const gkyl_gyrokinetic_app *app, const struct gk_species *gks)
{
  // Release various arrays and objects for a dynamic species.
  gkyl_array_release(gks->f1);
  gkyl_array_release(gks->fnew);
  gkyl_array_release(gks->bc_buffer);
  gkyl_array_release(gks->bc_buffer_lo_fixed);
  gkyl_array_release(gks->bc_buffer_up_fixed);

  if (gks->info.write_omega_cfl) {
    gkyl_array_release(gks->cflrate_ho);
  }

  int par_dir = app->cdim - 1; // Parallel direction index.

  // Copy BCs are allocated by default. Need to free.
  for (int d = 0; d < app->cdim; ++d) {
    if (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_SHEATH) {
      gkyl_bc_sheath_gyrokinetic_release(gks->bc_sheath_lo);
    } else if (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_TWISTSHIFT) {
      gkyl_bc_twistshift_release(gks->bc_ts_lo);
    } else if ((gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_COPY) ||
               (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_ABSORB) ||
               (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_REFLECT) ||
               (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_FIXED_FUNC)) {
      gkyl_bc_basic_gyrokinetic_release(gks->bc_lo[d]);
    }

    if (gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_SHEATH) {
      gkyl_bc_sheath_gyrokinetic_release(gks->bc_sheath_up);
    } else if (gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_TWISTSHIFT) {
      gkyl_bc_twistshift_release(gks->bc_ts_up);
    } else if ((gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_COPY) ||
               (gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_ABSORB) ||
               (gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_REFLECT) ||
               (gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_FIXED_FUNC)) {
      gkyl_bc_basic_gyrokinetic_release(gks->bc_up[d]);
    }
  }

  if (app->gk_geom->has_LCFS && app->cdim == 3) {
    // Free twishift memory.
    gkyl_bc_twistshift_release(gks->bc_ts_lo);
    gkyl_bc_twistshift_release(gks->bc_ts_up);
  }

  if (app->use_gpu) {
    gkyl_cu_free(gks->omega_cfl);
    gkyl_cu_free(gks->m0_max);
  } else {
    gkyl_free(gks->omega_cfl);
    gkyl_free(gks->m0_max);
  }

  // Release integrated moment memory.
  gk_species_moment_release(app, &gks->integ_moms);

  // Release integrated diag memory.
  gkyl_dynvec_release(gks->integ_diag);
  if (app->use_gpu) {
    gkyl_cu_free(gks->red_integ_diag);
    gkyl_cu_free(gks->red_integ_diag_global);
  } else {
    gkyl_free(gks->red_integ_diag);
                                    mkarr(app->use_gpu, 1, 1);
  // Buffer arrays for fixed function BCs on distribution function.
  gks->bc_buffer_lo_fixed = need_bc_buffer_lo_fixed ?
                              mkarr(app->use_gpu, gks->basis.num_basis, buff_sz) :
                              mkarr(app->use_gpu, 1, 1);
  gks->bc_buffer_up_fixed = need_bc_buffer_up_fixed ?
                              mkarr(app->use_gpu, gks->basis.num_basis, buff_sz) :
                              mkarr(app->use_gpu, 1, 1);

  if (gks->lower_bc[par_dir].type == GKYL_BC_GK_SPECIES_TWISTSHIFT &&
      gks->upper_bc[par_dir].type == GKYL_BC_GK_SPECIES_TWISTSHIFT) {
    // Local range extended in the BC dir, on the coarse grid.
    int lower_bcdir_ext[pdim], upper_bcdir_ext[pdim];
    for (int i = 0; i < pdim; i++) {
      lower_bcdir_ext[i] = gks->local.lower[i];
      upper_bcdir_ext[i] = gks->local.upper[i];
    }
    lower_bcdir_ext[par_dir] = gks->local_ext.lower[par_dir];
    upper_bcdir_ext[par_dir] = gks->local_ext.upper[par_dir];
    gkyl_sub_range_init(
      &gks->bc_ts_local_par_ext, &gks->local_ext, lower_bcdir_ext, upper_bcdir_ext
    );
  }

  for (int d = 0; d < cdim; ++d) {
    // Lower BC.
    if (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_SHEATH) {
      struct gkyl_range *sol_skin = gk_app_inp->geometry.has_LCFS ? &gks->local_lower_skin_par_sol :
                                                                    &gks->local_lower_skin[d];
      struct gkyl_range *sol_ghost = gk_app_inp->geometry.has_LCFS ?
                                       &gks->local_lower_ghost_par_sol :
                                       &gks->local_lower_ghost[d];
      gks->bc_sheath_lo = gkyl_bc_sheath_gyrokinetic_new(
        d, GKYL_LOWER_EDGE, gks->basis_on_dev, sol_skin, sol_ghost, gks->vel_map, cdim,
        2.0 * (gks->info.charge / gks->info.mass), app->use_gpu
      );
    } else if (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_TWISTSHIFT) {
      assert(cdim == 3);
      struct gkyl_bc_twistshift_inp tsinp = {
        .bc_dir = d,
        .shift_dir = 1, // y shift.
        .shear_dir = 0, // shift varies with x.
        .edge = GKYL_LOWER_EDGE,
        .cdim = cdim,
        .bcdir_ext_update_r = &gks->bc_ts_local_par_ext,
        .num_ghost = num_ghost,
        .basis = &gks->basis,
        .grid = &gks->grid,
        .use_gpu = app->use_gpu,
        .upsample_factor = app->core_parallel_bcs.ts_upsample_factor,
        .filter_half_width = app->core_parallel_bcs.ts_filter_half_width,
        .filter_cutoff_wavelength = app->core_parallel_bcs.ts_filter_cutoff_wavelength,
      };
      if (app->gk_geom->geometry_id == GKYL_GEOMETRY_TOKAMAK) {
        tsinp.shift_dg = app->delta_ts_x_lo;
      } else {
        tsinp.shift_func = app->gk_geom->lower_shift_func;
        tsinp.shift_func_ctx = app->gk_geom->lower_shift_ctx;
      }

      gks->bc_ts_lo = gkyl_bc_twistshift_inew(&tsinp);

    } else if ((gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_COPY) ||
               (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_ABSORB) ||
               (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_REFLECT) ||
               (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_FIXED_FUNC)) {
      if (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_REFLECT) {
        assert(
          d == cdim - 1
        ); // MF 2025/09/25: Reflecting BCs only allowed in the parallel direction.
      }

      gks->bc_lo[d] = gkyl_bc_basic_gyrokinetic_new(
        d, GKYL_LOWER_EDGE, gks->lower_bc[d].type, gks->basis_on_dev, &gks->local_lower_skin[d],
        &gks->local_lower_ghost[d], gks->f->ncomp, app->cdim, app->use_gpu
      );

      if (gks->lower_bc[d].type == GKYL_BC_GK_SPECIES_FIXED_FUNC) {
        // Project distribution desired in the ghost cell.
        struct gk_proj gk_proj_bc_lo;
        gk_species_projection_init(app, gks, gks->lower_bc[d].projection, &gk_proj_bc_lo);
        gk_species_projection_calc(app, gks, &gk_proj_bc_lo, gks->f1, 0.0); // Temporarily use f1.
        // Fill ghost cell with the boundary value.
        struct gkyl_bc_basic_gyrokinetic *gfss_bc_op = gkyl_bc_basic_gyrokinetic_new(
          d, GKYL_LOWER_EDGE, GKYL_BC_GK_SPECIES_BOUNDARY_VALUE, gks->basis_on_dev,
          &gks->local_lower_skin[d], &gks->local_lower_ghost[d], gks->f->ncomp, app->cdim,
          app->use_gpu
        );
        gkyl_bc_basic_gyrokinetic_advance(gfss_bc_op, gks->bc_buffer_lo_fixed, gks->f1);
        gkyl_bc_basic_gyrokinetic_release(gfss_bc_op);
        // Copy ghost range into buffer.
        gkyl_bc_basic_gyrokinetic_buffer_fixed_func(gks->bc_lo[d], gks->bc_buffer_lo_fixed, gks->f1);
        gkyl_array_clear(gks->f1, 0.0);
        gk_species_projection_release(app, &gk_proj_bc_lo);
      }
    }

    // Upper BC.
    if (gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_SHEATH) {
      struct gkyl_range *sol_skin = gk_app_inp->geometry.has_LCFS ? &gks->local_upper_skin_par_sol :
                                                                    &gks->local_upper_skin[d];
      struct gkyl_range *sol_ghost = gk_app_inp->geometry.has_LCFS ?
                                       &gks->local_upper_ghost_par_sol :
                                       &gks->local_upper_ghost[d];
      gks->bc_sheath_up = gkyl_bc_sheath_gyrokinetic_new(
        d, GKYL_UPPER_EDGE, gks->basis_on_dev, sol_skin, sol_ghost, gks->vel_map, cdim,
        2.0 * (gks->info.charge / gks->info.mass), app->use_gpu
      );
    } else if (gks->upper_bc[d].type == GKYL_BC_GK_SPECIES_TWISTSHIFT) {
      assert(cdim == 3);
      struct gkyl_bc_twistshift_inp tsinp = {
        .bc_dir = d,
        .shift_dir = 1, // y shift.
        .shear_dir = 0, // shift varies with x.
        .edge = GKYL_UPPER_EDGE,
        .cdim = cdim,
        .bcdir_ext_update_r = &gks->bc_ts_local_par_ext,
        .num_ghost = num_ghost,
        .basis = &gks->basis,
        .grid = &gks->grid,
        .use_gpu = app->use_gpu,

item.aggregated_output:
)
{
  struct timespec wst = gkyl_wall_clock();

  // Package metadata.
  gkyl_msgpack_map_elem_set_double(gks->io_meta_phase_len, gks->io_meta_phase, "time", tm);
  gkyl_msgpack_map_elem_set_uint(gks->io_meta_phase_len, gks->io_meta_phase, "frame", frame);
  struct gkyl_msgpack_map_elem desc[] = {{
    .key = "Description",
    .elem_type = GKYL_MP_STRING,
    .cval = "Collisionless flux at cell surface.",
  }};
  int io_meta_len[] = {gks->io_meta_phase_len, app->gk_geom->io_meta_basic_len, 1};
  const struct gkyl_msgpack_map_elem *io_meta[] = {
    gks->io_meta_phase, app->gk_geom->io_meta_basic, desc
  };
  struct gkyl_msgpack_data *mt =
    gkyl_msgpack_create_union(sizeof(io_meta_len) / sizeof(int), io_meta_len, io_meta);

  // Write gkcls->flux_surf
  const char *fmt = "%s-%s_collisionless_surf_flux_%d.gkyl";
  int sz = gkyl_calc_strlen(fmt, app->name, gks->info.name, frame);
  char fileNm[sz + 1]; // ensures no buffer overflow
  snprintf(fileNm, sizeof fileNm, fmt, app->name, gks->info.name, frame);
  gkyl_array_copy(gkcls->flux_surf_ho, gkcls->flux_surf);
  gkyl_comm_array_write(gks->comm, &gks->grid, &gks->local, mt, gkcls->flux_surf_ho, fileNm);

  gkyl_msgpack_data_release(mt);
  app->stat.species_diag_io_tm += gkyl_time_diff_now_sec(wst);
  app->stat.n_io += 1;
}

static void
gk_species_collisionless_init_passive(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls,
  const bool *is_zero_flux, const enum gkyl_gyrokinetic_bc_type *bctype_conf,
  const struct gkyl_basis *surf_basis
)
{
  int cdim = app->cdim;

  gkcls->flux_surf = mkarr(app->use_gpu, cdim * surf_basis->num_basis, gks->local_ext.volume);

  gkcls->passive_speeds = mkarr(app->use_gpu, cdim * app->basis.num_basis, app->local_ext.volume);
  gkcls->passive_speeds_ho =
    app->use_gpu ? mkarr(false, gkcls->passive_speeds->ncomp, gkcls->passive_speeds->size) :
                   gkyl_array_acquire(gkcls->passive_speeds);

  struct gkyl_eval_on_nodes *speeds_proj = gkyl_eval_on_nodes_inew(&(struct gkyl_eval_on_nodes_inp){
    .grid = &app->grid,
    .basis = &app->basis,
    .num_ret_vals = cdim,
    .eval = gks->info.collisionless.passive_speeds,
    .ctx = gks->info.collisionless.passive_speeds_ctx,
    .c2p_func = eval_on_nodes_c2p_position_func,
    .c2p_func_ctx = app->position_map,
  });
  gkyl_eval_on_nodes_advance(speeds_proj, 0.0, &app->local, gkcls->passive_speeds_ho);
  gkyl_eval_on_nodes_release(speeds_proj);
  gkyl_array_copy(gkcls->passive_speeds, gkcls->passive_speeds_ho);

  // Sync speeds.
  int num_periodic_dir = app->num_periodic_dir;
  gkyl_comm_array_per_sync(
    app->comm, &app->local, &app->local_ext, num_periodic_dir, app->periodic_dirs,
    gkcls->passive_speeds
  );
  gkyl_comm_array_sync(app->comm, &app->local, &app->local_ext, gkcls->passive_speeds);

  gkcls->passive_surf_flux_op = gkyl_gk_collisionless_passive_flux_new(
    &gks->grid, &app->basis, &gks->basis, gkcls->passive_speeds, gks->info.charge, gks->info.mass,
    app->gk_geom, app->dg_geom, app->gk_dg_geom, gks->vel_map, bctype_conf, app->use_gpu
  );

  struct gkyl_dg_gyrokinetic_passive_auxfields passive_aux = {
    .flux_surf = gkcls->flux_surf,
    .speeds = gkcls->passive_speeds,
  };
  gkcls->passive_slvr = gkyl_dg_updater_gyrokinetic_passive_new(
    &gks->grid, &app->basis, &gks->basis, &app->local, &gks->local, is_zero_flux, gks->info.charge,
    gks->info.mass, app->gk_geom, gks->vel_map, &passive_aux, app->use_gpu
  );

  if (gkcls->write_diagnostics) {
    gkyl_msgpack_map_elem_set_double(gks->io_meta_conf_len, gks->io_meta_conf, "time", 0.0);
    gkyl_msgpack_map_elem_set_uint(gks->io_meta_conf_len, gks->io_meta_conf, "frame", 0);
    struct gkyl_msgpack_map_elem desc[] = {{
      .key = "Description",
      .elem_type = GKYL_MP_STRING,
      .cval = "Conf-space passive advection speeds.",
    }};
    int io_meta_len[] = {gks->io_meta_conf_len, app->gk_geom->io_meta_basic_len, 1};
    const struct gkyl_msgpack_map_elem *io_meta[] = {
      gks->io_meta_conf, app->gk_geom->io_meta_basic, desc
    };
    struct gkyl_msgpack_data *mt =
      gkyl_msgpack_create_union(sizeof(io_meta_len) / sizeof(int), io_meta_len, io_meta);

    const char *fmt = "%s-%s_passive_speeds_%d.gkyl";
    int sz = gkyl_calc_strlen(fmt, app->name, gks->info.name, 0);
    char fileNm[sz + 1];
    snprintf(fileNm, sizeof fileNm, fmt, app->name, gks->info.name, 0);
    gkyl_comm_array_write(app->comm, &app->grid, &app->local, mt, gkcls->passive_speeds_ho, fileNm);

    gkyl_msgpack_data_release(mt);
  }

  gkcls->flux_func = gk_species_collisionless_passive_flux;
  gkcls->rhs_func = gk_species_collisionless_passive_rhs;
}

void
gk_species_collisionless_init(
  struct gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls
)
{
  gkcls->collisionless_id = gks->info.collisionless.type;
  gkcls->write_diagnostics = gks->info.collisionless.write_diagnostics;

  gkcls->write_diags_func = gk_species_collisionless_write_diags_disabled;
  gkcls->flux_func = gk_species_collisionless_flux_disabled;
  gkcls->rhs_func = gk_species_collisionless_rhs_disabled;

  if (gkcls->collisionless_id) {
    int cdim = app->cdim, vdim = gks->info.vdim;
    int pdim = cdim + vdim;

    // Determine which directions are zero-flux. By default
    // we do not have zero-flux boundary conditions in any direction.
    bool is_zero_flux[2 * GKYL_MAX_DIM] = {false};
    for (int dir = 0; dir < app->cdim; ++dir) {
      if (gks->lower_bc[dir].type == GKYL_BC_GK_SPECIES_ZERO_FLUX) {
        is_zero_flux[dir] = true;
      }
      if (gks->upper_bc[dir].type == GKYL_BC_GK_SPECIES_ZERO_FLUX) {
        is_zero_flux[dir + pdim] = true;
      }
    }

    // Need to figure out size of flux_surf by finding size of surface basis set
    struct gkyl_basis surf_basis;
    struct gkyl_basis surf_vpar_basis;
    // Define surface bases
    if (app->poly_order > 1) {
      gkyl_cart_modal_serendip(&surf_basis, pdim - 1, app->poly_order);
    } else {
      gkyl_cart_modal_serendip(&surf_vpar_basis, pdim - 1, app->poly_order);
      if (vdim > 1) {
        gkyl_cart_modal_gkhybrid(&surf_basis, cdim - 1, vdim); // p=2 in vparallel
      } else {
        gkyl_cart_modal_serendip(&surf_basis, pdim - 1, 2); // p=2 in vparallel
      }
    }

    enum gkyl_gyrokinetic_bc_type bctype_conf[2 * GKYL_MAX_CDIM];
    for (int d = 0; d < app->cdim; d++) {
      bctype_conf[d] = gks->lower_bc[d].type;
      bctype_conf[GKYL_MAX_CDIM + d] = gks->upper_bc[d].type;
    }

    if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_PASSIVE) {
      gk_species_collisionless_init_passive(app, gks, gkcls, is_zero_flux, bctype_conf, &surf_basis);
    } else {
      // Allocate arrays to store surface phase space flux.
      gkcls->flux_surf = mkarr(
        app->use_gpu, cdim * surf_basis.num_basis + surf_vpar_basis.num_basis, gks->local_ext.volume
      );
      gkcls->conf_alpha_surf =
        mkarr(app->use_gpu, cdim * surf_basis.num_basis, gks->local_ext.volume);

      if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_EM_BPERP) {
        // Parallel component of magnetic vector potential.
        gkcls->apar = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
        gkcls->apardot = mkarr(app->use_gpu, app->basis.num_basis, app->local_ext.volume);
      } else {
        gkcls->apar = gkyl_array_acquire(app->field->phi_smooth); // Not used.
        gkcls->apardot = gkyl_array_acquire(app->field->phi_smooth); // Not used.
      }

      gkcls->surf_flux_op = gkyl_gk_collisionless_flux_new(
        &gks->grid, &app->basis, &gks->basis, gks->info.charge, gks->info.mass,
        gkcls->collisionless_id, app->gk_geom, app->dg_geom, app->gk_dg_geom, gks->vel_map,
        bctype_conf, app->use_gpu
      );

      struct gkyl_dg_gyrokinetic_auxfields aux_inp = {
        .flux_surf = gkcls->flux_surf,
        .phi = gks->gyro_phi,
        .apar = gkcls->apar,
        .apardot = gkcls->apardot,
      };
      // Create solver.
      gkcls->slvr = gkyl_dg_updater_gyrokinetic_new(
        &gks->grid, &app->basis, &gks->basis, &app->local, &gks->local, is_zero_flux,
        gks->info.charge, gks->info.mass, gkcls->collisionless_id, app->gk_geom, gks->vel_map,
        &aux_inp, app->use_gpu
      );

      gkcls->flux_func = gk_species_collisionless_flux_enabled;
      gkcls->rhs_func = gk_species_collisionless_rhs_enabled;
    }

    gkcls->scale_fac = 1.0; // Not used if scale_factor in input file is not given.
    gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_disabled;
    if (1.0e-16 < fabs(gks->info.collisionless.scale_factor)) {
      gkcls->scale_fac = gks->info.collisionless.scale_factor;
      gkcls->fdot_scaling = gk_species_collisionless_fdot_scaling_enabled;
    }

    if (gkcls->write_diagnostics) {
      gkcls->flux_surf_ho = mkarr(false, gkcls->flux_surf->ncomp, gkcls->flux_surf->size);
      gkcls->write_diags_func = gk_species_collisionless_write_diags_enabled;
    }
  }
}

