  enum gkyl_gk_collisionless_type type, const enum gkyl_gyrokinetic_bc_type *bctype_conf
)
{
  if (type == GKYL_GK_COLLISIONLESS_ES) {
    for (int d = 0; d < cdim; ++d) {
