#include <assert.h>
#include <gkyl_gyrokinetic_priv.h>

static void
eval_on_nodes_c2p_position_func(const double *xcomp, double *xphys, void *ctx)
{
  struct gkyl_position_map *gpm = ctx;
  gkyl_position_map_eval_mc2nu(gpm, xcomp, xphys);
}

static void
gk_species_collisionless_flux_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  // Do nothing.
}

static void
gk_species_collisionless_flux_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  // Compute the surface expansion of the phase space flux
  // Note: Each cell stores the *lower* surface expansions of the
  // phase space flux, so local_ext range needed to index the output
  // values of flux_surf even though we only loop over local ranges
  // to avoid evaluating quantities such as geometry in ghost cells
  // where they are not defined.
  gkyl_gk_collisionless_flux_surf(
    gkcls->surf_flux_op, &app->local, &species->local, &app->local_ext, &species->local_ext,
    species->gyro_phi, fin, gkcls->flux_surf, gkcls->conf_alpha_surf, species->cflrate
  );
}

static void
gk_species_collisionless_rhs_disabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
}

static void
gk_species_collisionless_rhs_enabled(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  struct timespec wst = gkyl_wall_clock();

  gkcls->flux_func(app, species, gkcls, fin);

  gk_species_collisionless_influx_advance(
    app, species, &species->collisionless_influx, gkcls->flux_surf, gkcls->conf_alpha_surf
  );

  gkyl_dg_updater_gyrokinetic_advance(gkcls->slvr, &species->local, fin, species->cflrate, rhs);

  gkcls->fdot_scaling(app, species, gkcls, rhs, species->cflrate, &species->local);

  app->stat.species_collisionless_tm += gkyl_time_diff_now_sec(wst);
}

static void
gk_species_collisionless_passive_flux(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin
)
{
  gkyl_gk_collisionless_passive_flux_surf(
    gkcls->passive_surf_flux_op, &app->local, &species->local, &app->local_ext, &species->local_ext,
    fin, gkcls->flux_surf, species->cflrate
  );
}

static void
gk_species_collisionless_passive_rhs(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  struct timespec wst = gkyl_wall_clock();

  gkcls->flux_func(app, species, gkcls, fin);

  gkyl_dg_updater_gyrokinetic_passive_advance(
    gkcls->passive_slvr, &species->local, fin, species->cflrate, rhs
)
{
  gkcls->flux_func(app, species, gkcls, fin);
}

void
gk_species_collisionless_rhs(
  gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
  const struct gkyl_array *fin, struct gkyl_array *rhs
)
{
  gkcls->rhs_func(app, species, gkcls, fin, rhs);
}

void
gk_species_collisionless_write_diags(
  gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls, double tm,
  int frame
)
{
  gkcls->write_diags_func(app, gks, gkcls, tm, frame);
}

void
gk_species_collisionless_release(
  const struct gkyl_gyrokinetic_app *app, const struct gk_collisionless *gkcls
)
{
  if (gkcls->collisionless_id) {
    gkyl_array_release(gkcls->flux_surf);

    if (gkcls->collisionless_id == GKYL_GK_COLLISIONLESS_PASSIVE) {
      gkyl_array_release(gkcls->passive_speeds);
      gkyl_array_release(gkcls->passive_speeds_ho);
      gkyl_gk_collisionless_passive_flux_release(gkcls->passive_surf_flux_op);
      gkyl_dg_updater_gyrokinetic_passive_release(gkcls->passive_slvr);
    } else {
      gkyl_array_release(gkcls->conf_alpha_surf);
      gkyl_array_release(gkcls->apar);
      gkyl_array_release(gkcls->apardot);
      gkyl_gk_collisionless_flux_release(gkcls->surf_flux_op);
      gkyl_dg_updater_gyrokinetic_release(gkcls->slvr);
    }

    if (gkcls->write_diagnostics) {
      gkyl_array_release(gkcls->flux_surf_ho);
    }
  }
}

void
gk_species_collisionless_reset(
  gkyl_gyrokinetic_app *app, double tm, struct gk_species *gks, struct gk_collisionless *gkcls,
  struct gkyl_gyrokinetic_collisionless gkcls_inp
)
{
};

struct gk_collisionless {
  enum gkyl_gk_collisionless_type collisionless_id; // Type of collisionless terms.
  bool write_diagnostics; // Whether to write diagnostics out.
  double scale_fac; // Factor multiplying collisionless terms.

  // Organization of the different equation objects and the required data and solvers
  union {
    // Charged (gyrokinetic) species ............................................ //
    struct {
      struct gkyl_array *flux_surf; // Array for surface phase space flux
      struct gkyl_array *conf_alpha_surf; // Array for normal phase-space characteristics
      struct gkyl_array *flux_surf_ho; // Host array for surface phase space flux
      struct gkyl_array *apar; // A_parallel.
      struct gkyl_array *apardot; // d/dt A_parallel.

      struct gkyl_gk_collisionless_flux *surf_flux_op; // Collisionless fluxes (GK/EM cases).
      gkyl_dg_updater_gyrokinetic *slvr; // Collisionless solver (GK/EM cases).

      // Passive advection (only for GKYL_GK_COLLISIONLESS_PASSIVE).
      struct gkyl_array *passive_speeds; // Conf-space passive speeds.
      struct gkyl_array *passive_speeds_ho; // Host copy of passive_speeds.
      struct gkyl_gk_collisionless_passive_flux *passive_surf_flux_op; // Passive flux updater.
      gkyl_dg_updater_gyrokinetic_passive *passive_slvr; // Passive collisionless solver.

      // Methods chosen at runtime.
      void (*flux_func)(
        gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless *gkcls,
        const struct gkyl_array *fin
      );
    };
    // Neutral (Vlasov) species ............................................ //
    struct {
      struct gkyl_array *alpha_surf; // array for surface phase space flux (v^i = v . e^i)
      struct gkyl_array
        *sgn_alpha_surf; // array for the sign of the surface phase space flux at quadrature points
      // utilized for numerical flux function
      // F = alpha_surf/2 ( (f^+ + f^-) - sign_alpha_surf*(f^+ - f^-) )
      struct gkyl_array
        *const_sgn_alpha; // boolean array for if the surface phase space flux is single signed
      // if true, numerical flux function inside kernels simplifies to
      // F = alpha_surf*f^- (if sign_alpha_surf = 1),
      // F = alpha_surf*f^+ (if sign_alpha_surf = -1)

      gkyl_dg_updater_vlasov *vlasov_slvr; // Vlasov solver.
    };
  };
  void (*rhs_func)(
    gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls,
    const struct gkyl_array *fin, struct gkyl_array *rhs
  );
  void (*fdot_scaling)(
    gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls,
    struct gkyl_array *rhs, struct gkyl_array *cflrate, struct gkyl_range *rng
  );
  void (*write_diags_func)(
    gkyl_gyrokinetic_app *app, struct gk_species *gks, struct gk_collisionless *gkcls, double tm,
    int frame
  );
  // Methods for neutral species.
  void (*rhs_func_neut)(
    gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_collisionless *gkcls,
    const struct gkyl_array *fin, struct gkyl_array *rhs
  );
  void (*write_diags_func_neut)(
    gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_collisionless *gkcls,
    double tm, int frame
  );
};

// App-level operations that modify a collisionless surface flux before it is
// lifted into the DG RHS. The first operation is the sheath return flux; the
// structure deliberately leaves room for prescribed and transfer operations.
struct gk_collisionless_influx {
  bool lower_sheath;
  bool upper_sheath;
  void (*advance)(
    gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless_influx *influx,
    struct gkyl_array *flux_surf, const struct gkyl_array *alpha_surf
  );
};

struct gk_lbo_collisions {
  enum gkyl_collision_id collision_id; // type of collisions
  bool write_diagnostics; // Whether to write diagnostics out.
  bool not_in_dfdt; // Whether to not add collision contribution to df/dt

  struct gkyl_array *self_nu; // Self-collision frequency.
  struct gkyl_array *boundary_corrections; // LBO boundary corrections.
  struct gkyl_mom_calc_bcorr *bcorr_calc; // LBO boundary corrections calculator.
  // Methods for neutral species.
  void (*rhs_func_neut)(
    gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_collisionless *gkcls,
    const struct gkyl_array *fin, struct gkyl_array *rhs
  );
  void (*write_diags_func_neut)(
    gkyl_gyrokinetic_app *app, struct gk_neut_species *gkns, struct gk_collisionless *gkcls,
    double tm, int frame
  );
};

// App-level operations that modify a collisionless surface flux before it is
// lifted into the DG RHS. The first operation is the sheath return flux; the
// structure deliberately leaves room for prescribed and transfer operations.
struct gk_collisionless_influx {
  bool lower_sheath;
  bool upper_sheath;
  void (*advance)(
    gkyl_gyrokinetic_app *app, struct gk_species *species, struct gk_collisionless_influx *influx,
    struct gkyl_array *flux_surf, const struct gkyl_array *alpha_surf
  );
};

struct gk_lbo_collisions {
  enum gkyl_collision_id collision_id; // type of collisions
