static bool
gk_sheath_conducting_flux_has_inward_partner(
  const struct gkyl_gk_sheath_conducting_flux *up, const double *alpha_out, const double *alpha_in
)
{
  int face_basis = up->surf_basis.num_basis;
  double edge_sign = up->edge == GKYL_LOWER_EDGE ? -1.0 : 1.0;
  bool has_outgoing = false;

  for (int node = 0; node < face_basis; ++node) {
    if (edge_sign * alpha_out[up->dir * face_basis + node] > 0.0) {
      has_outgoing = true;
      if (edge_sign * alpha_in[up->dir * face_basis + node] >= 0.0) {
        return false;
      }
    }
  }
  return has_outgoing;
}

static void
gk_sheath_conducting_flux_advance_cpu(
  gkyl_gk_sheath_conducting_flux *up, const struct gkyl_array *phi_sheath,
  const struct gkyl_array *gyro_phi, const struct gkyl_array *phi_wall,
  const struct gkyl_array *fin, struct gkyl_array *flux_surf
