        xc, up->phase_grid.dx, vmap, vmap_sq, flux_op->charge, flux_op->mass, dgs, gkdgs, bmag,
        jac_l, jac_r, phi, fhat, zero, low_flux, alpha_out
      );
      flux_op->flux_surf_edge_up[up->dir](
