        flux_op->mass, dgs, gkdgs, bmag, jac_l, jac_r, phi, zero, zero, scratch_flux, alpha_in
      );
    }

    if (gk_sheath_conducting_flux_has_inward_partner(up, alpha_out, alpha_in)) {
      double reflected_flux[face_basis];
      double *target_flux = gkyl_array_fetch(flux_surf, partner_loc) + up->dir * face_basis;
      up->surf_basis.flip_odd_sign(up->cdim - 1, low_flux + up->dir * face_basis, reflected_flux);
      for (int basis_idx = 0; basis_idx < face_basis; ++basis_idx) {
        target_flux[basis_idx] -= reflected_flux[basis_idx];
      }
    }
  }
