#pragma once

#include <gkyl_hyper_dg.h>
#include <gkyl_dg_eqn.h>
#include <gkyl_dg_updater_gyrokinetic.h>

struct gkyl_dg_updater_gyrokinetic {
  bool use_gpu; // Boolean for if the update is performed on GPUs
  struct gkyl_dg_eqn *eqn_gyrokinetic; // Equation object
  struct gkyl_hyper_dg *up_gyrokinetic; // solvers for specific gyrokinetic equation

  double gyrokinetic_tm; // total time spent in computing gyrokinetic equation
};
#include <gkyl_bc_basic_gyrokinetic.h>
#include <gkyl_bc_basic_gyrokinetic_priv.h>
#include <gkyl_alloc.h>
#include <gkyl_alloc_flags_priv.h>

// Private function to create a pointer to the function that applies the BC,
// i.e., the array_copy_func applied to expansion coefficients in ghost cell.
struct gkyl_array_copy_func *
gkyl_bc_basic_gyrokinetic_create_arr_copy_func(
  int dir, enum gkyl_edge_loc edge, int cdim, enum gkyl_gyrokinetic_bc_type bctype,
  const struct gkyl_basis *basis, int ncomp, bool use_gpu
)
{
#ifdef GKYL_HAVE_CUDA
  if (use_gpu) {
    return gkyl_bc_basic_gyrokinetic_create_arr_copy_func_cu(dir, edge, cdim, bctype, basis, ncomp);
