  if (up->use_gpu) {
    gkyl_cu_free(up->array_copy_func->ctx_on_dev);
    gkyl_cu_free(up->array_copy_func->on_dev);
  }
  gkyl_free(up->array_copy_func->ctx);
  gkyl_free(up->array_copy_func);
  // Release updater memory.
  gkyl_free(up);
}

