    const struct gkyl_dg_surf_geom *dgs =
      gkyl_dg_geom_get_surf(flux_op->dg_geom, up->dir, geom_idx);
    const struct gkyl_gk_dg_surf_geom *gkdgs =
      gkyl_gk_dg_geom_get_surf(flux_op->gk_dg_geom, up->dir, geom_idx);
